def choose_move(observation):
    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def safe_pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def best_target(targets, sx, sy, far=False):
        if not targets:
            return None
        best = None
        best_score = None
        for t in targets:
            tx, ty = safe_pos(t, None)
            if tx is None:
                continue
            score = abs(tx - sx) + abs(ty - sy)
            if far:
                score = -score
            if best is None or score < best_score:
                best = (tx, ty)
                best_score = score
        return best

    env = observation.get("environment_name", "resource_collection")
    sx, sy = safe_pos(observation.get("self_position", (0, 0)))
    ox, oy = safe_pos(observation.get("opponent_position", (sx, sy)))

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return [clamp_step(sx, ox), clamp_step(sy, oy)]
        gw = observation.get("grid_width", 0)
        gh = observation.get("grid_height", 0)
        corners = []
        if gw and gh:
            corners = [(0, 0), (0, gh - 1), (gw - 1, 0), (gw - 1, gh - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = best_target(corners, ox, oy, far=True)
        if target is None:
            target = (sx - (ox - sx), sy - (oy - sy))
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("targets") or []
        target = best_target(targets, sx, sy, far=False)
        if target is None:
            # drift toward opponent or center if available
            gw = observation.get("grid_width")
            gh = observation.get("grid_height")
            if gw is not None and gh is not None:
                target = (gw // 2, gh // 2)
            else:
                target = (ox, oy)
        return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

    resources = observation.get("resources") or observation.get("resource_positions") or []
    target = best_target(resources, sx, sy, far=False)
    if target is None:
        # if no resource visible, move toward opponent to explore or contest
        return [clamp_step(sx, ox), clamp_step(sy, oy)]
    return [clamp_step(sx, target[0]), clamp_step(sy, target[1])]

